# frozen_string_literal: true

require 'digest'
require 'json'
require 'time'

# Detailed stage profiler for the CURRENT LocalVertexNormalizer.
#
# It reuses the manifest generated by lvn_many_solids_benchmark.rb and profiles
# the exact same target PIDs. Profiling is enabled with:
#
#   report: true, write_report: false
#
# The built-in debug profiler records inclusive nested timings. This script
# reconstructs the event nesting and calculates exclusive timings so that:
#
#   sum(exclusive stage seconds) + unattributed seconds == profile total seconds
#
# Usage:
#
#   load 'C:/path/to/dev/lvn_stage_detail_profile_benchmark.rb'
#
#   LvnStageDetailProfileBenchmark.run(
#     revision: 'FULL_COMMIT_SHA'
#   )
module LvnStageDetailProfileBenchmark
  SCHEMA = 'ulol.lvn.stage_detail_profile_benchmark.v1'
  MANIFEST_SCHEMA = 'ulol.lvn.many_solids_benchmark.targets.v1'
  CLOCK = Process::CLOCK_MONOTONIC
  EPSILON_SECONDS = 1.0e-9

  module StageProfilerExtensions
    private

    def normalize_entity_before_final_coplanar_face_merge(entity)
      measure_diagnostic_stage(:core_before_final_coplanar_merge) { super }
    end

    def normalize_entity_before_normalized_input_fast_path(entity)
      measure_diagnostic_stage(:full_rebuild_pipeline) { super }
    end

    def normalized_input_fast_path_candidate?(entity)
      measure_diagnostic_stage(:fast_path_candidate_probe) { super }
    end

    def try_normalized_input_fast_path(entity)
      measure_diagnostic_stage(:fast_path_exact_validation) { super }
    end

    def snapshot_final_coplanar_baseline(entities)
      measure_diagnostic_stage(:final_coplanar_baseline_snapshot_total) { super }
    end

    def normalize_entity(entity)
      previous_detail = @lvn_stage_detail_profile_v1
      @lvn_stage_detail_profile_v1 = new_lvn_stage_detail_profile_v1
      super
    ensure
      profile = @local_vertex_normalizer_diagnostic_profile
      if profile && @lvn_stage_detail_profile_v1
        profile[:hotspot_detail] = deep_dup_lvn_stage_detail_profile_v1(
          @lvn_stage_detail_profile_v1
        )
      end
      @lvn_stage_detail_profile_v1 = previous_detail
    end

    def source_boundary_triangle_records(face, source_face_key)
      detail_add_v1(:snapshot, :source_boundary_face_calls)
      result = measure_diagnostic_stage(
        :detail_source_boundary_face_total,
        emit: false,
        record_event: false
      ) { super }
      detail_add_v1(:snapshot, :source_boundary_output_triangles, result.length)
      result
    end

    def classify_exact_patch_loops(loops, drop_axis)
      detail_add_v1(:snapshot, :loop_classification_calls)
      detail_add_v1(:snapshot, :input_loop_count, loops.length)
      detail_add_v1(
        :snapshot,
        :input_boundary_vertex_count,
        loops.sum { |loop| Array(loop).length }
      )
      result = measure_diagnostic_stage(
        :detail_loop_classification,
        emit: false,
        record_event: false
      ) { super }
      detail_add_v1(:snapshot, :classified_hole_count, Array(result && result[1]).length)
      result
    end

    def triangulate_exact_polygon_with_holes(outer, holes, drop_axis)
      detail_add_v1(:snapshot, :exact_polygon_calls)
      detail_add_v1(:snapshot, :outer_vertex_count, outer.length)
      detail_add_v1(:snapshot, :hole_count, holes.length)
      detail_add_v1(
        :snapshot,
        :hole_vertex_count,
        holes.sum { |hole| Array(hole).length }
      )
      cache_stats = @local_vertex_normalizer_exact_polygon_cache_stats
      before = cache_stats && cache_stats.dup
      result = measure_diagnostic_stage(
        :detail_exact_polygon_total,
        emit: false,
        record_event: false
      ) { super }
      detail_add_v1(:snapshot, :exact_polygon_output_triangles, result.length)
      result
    ensure
      detail_add_stats_delta_v1(
        :snapshot,
        cache_stats,
        before,
        {
          hits: :exact_polygon_cache_hits,
          misses: :exact_polygon_cache_misses,
          stored_triangle_count: :exact_polygon_cached_triangles_stored
        }
      )
    end

