    def validate_triangle_intersections!(triangles)
      detail_add_v1(:intersection, :validation_calls)
      detail_add_v1(:intersection, :validation_triangles, triangles.length)
      detail_add_v1(
        :intersection,
        :possible_pair_count,
        (triangles.length * (triangles.length - 1)) / 2
      )
      measure_diagnostic_stage(
        :detail_intersection_validation_total,
        emit: false,
        record_event: false
      ) { super }
    end

    def collect_triangle_intersection_failures(triangles, partition_ids: nil)
      detail_add_v1(:intersection, :collect_calls)
      detail_add_v1(:intersection, :collect_triangle_count, triangles.length)
      clean_stats = @local_vertex_normalizer_triangle_intersection_clean_cache_stats
      before = clean_stats && clean_stats.dup
      result = measure_diagnostic_stage(
        :detail_intersection_collect_total,
        emit: false,
        record_event: false
      ) do
        super(triangles, partition_ids: partition_ids)
      end
      detail_add_v1(
        :intersection,
        :tested_pairs,
        result && result[:tested_pairs].to_i
      )
      detail_add_v1(
        :intersection,
        :invalid_pairs,
        Array(result && result[:pairs]).length
      )
      result
    ensure
      detail_add_stats_delta_v1(
        :intersection,
        clean_stats,
        before,
        {
          hits: :clean_cache_hits,
          misses: :clean_cache_misses,
          stores: :clean_cache_stores,
          evictions: :clean_cache_evictions,
          bypassed_small: :clean_cache_bypassed_small,
          bypassed_partitioned: :clean_cache_bypassed_partitioned,
          saved_tested_pairs: :clean_cache_saved_tested_pairs
        }
      )
    end

    def triangle_intersection_clean_cache_key(triangles)
      detail_add_v1(:intersection, :clean_cache_key_calls)
      measure_diagnostic_stage(
        :detail_intersection_clean_cache_key,
        emit: false,
        record_event: false
      ) { super }
    end

    def each_overlapping_integer_aabb_pair(aabbs, &block)
      detail_add_v1(:intersection, :broad_phase_calls)
      yielded = 0
      wrapped = if block
                  proc do |*arguments|
                    yielded += 1
                    block.call(*arguments)
                  end
                end
      measure_diagnostic_stage(
        :detail_intersection_broad_phase_total,
        emit: false,
        record_event: false
      ) do
        super(aabbs, &(wrapped || block))
      end
    ensure
      detail_add_v1(:intersection, :broad_phase_yielded_pairs, yielded)
    end

    def exact_triangle_intersection_allowed?(triangle_a, triangle_b)
      detail_add_v1(:intersection, :exact_predicate_calls)
      measure_diagnostic_stage(
        :detail_intersection_exact_predicate_total,
        emit: false,
        record_event: false
      ) { super }
    end

    def coplanar_triangle_intersection_allowed?(triangle_a, triangle_b, shared)
      detail_add_v1(:intersection, :coplanar_predicate_calls)
