    end

    def coplanar_shared_edge_intersection_decision(
      triangle_a,
      triangle_b,
      shared
    )
      detail_add_v1(:intersection, :shared_edge_fast_path_calls)
      result = measure_diagnostic_stage(
        :detail_intersection_shared_edge_fast_path,
        emit: false,
        record_event: false
      ) { super }
      key = if result.nil?
              :shared_edge_fast_path_fallbacks
            elsif result
              :shared_edge_fast_path_allowed
            else
              :shared_edge_fast_path_rejected
            end
      detail_add_v1(:intersection, key)
      result
    end

