    )
      detail_add_v1(:intersection, :noncoplanar_predicate_calls)
      measure_diagnostic_stage(
        :detail_intersection_noncoplanar_total,
        emit: false,
        record_event: false
      ) { super }
    end

    def triangle_plane_parameter_interval(
      triangle,
      plane_point,
      plane_normal,
      direction
    )
      detail_add_v1(:intersection, :plane_interval_calls)
      measure_diagnostic_stage(
        :detail_intersection_plane_interval,
        emit: false,
        record_event: false
      ) { super }
    end

    def new_lvn_stage_detail_profile_v1
      {
        snapshot: Hash.new(0),
        intersection: Hash.new(0)
      }
    end

    def detail_add_v1(section, key, amount = 1)
      detail = @lvn_stage_detail_profile_v1
      return unless detail

      detail[section][key] += amount.to_i
    end

    def detail_add_stats_delta_v1(section, current, before, mapping)
      return unless current && before

      mapping.each do |source_key, target_key|
        delta = current[source_key].to_i - before[source_key].to_i
        detail_add_v1(section, target_key, delta) if delta.positive?
      end
    end

    def deep_dup_lvn_stage_detail_profile_v1(value)
      case value
      when Hash
        value.each_with_object({}) do |(key, item), result|
          result[key] = deep_dup_lvn_stage_detail_profile_v1(item)
        end
      when Array
        value.map { |item| deep_dup_lvn_stage_detail_profile_v1(item) }
      else
        value
      end
    end
  end

  module_function

  def run(
    revision:,
    label: 'current',
    manifest_path: nil,
    output_directory: nil,
    verify_after_rollback: true
  )
    model = Sketchup.active_model
    ensure_saved_model!(model)
    install_stage_extensions!

    revision = revision.to_s.strip
    raise ArgumentError, 'revision must be an explicit commit SHA' if revision.empty?

    manifest_path ||= default_manifest_path(model)
    manifest = load_manifest(model, manifest_path)
    targets = manifest_targets(manifest)

    verify_target_set!(model, targets)

    output_directory ||= File.dirname(model.path)
    timestamp = Time.now.strftime('%Y%m%d_%H%M%S')
    model_name = sanitize_label(
      File.basename(model.path, File.extname(model.path))
    )
    output_path = File.join(
      output_directory,
      "lvn_stage_detail_profile_#{model_name}_#{revision[0, 12]}_#{timestamp}.json"
    )

    print_header(
      model: model,
      revision: revision,
      manifest_path: manifest_path,
      target_count: targets.length
    )

    operation_started = model.start_operation(
      'LVN stage profile benchmark',
      true
    )
    raise 'SketchUp start_operation returned false' if operation_started == false

    samples = []
    batch_started = nil
    batch_finished = nil
    abort_error = nil

    begin
      GC.start
      batch_started = Process.clock_gettime(CLOCK)

      targets.each_with_index do |target, index|
        entity = resolve_top_level_entity(model, target[:pid])

        unless entity
          samples << missing_sample(target)
          print_sample(samples.last, index + 1, targets.length)
          next
        end

        sample = profile_target(entity, target)
        samples << sample
        print_sample(sample, index + 1, targets.length)
      end

      batch_finished = Process.clock_gettime(CLOCK)
    ensure
      begin
        model.abort_operation if operation_started
      rescue StandardError => error
        abort_error = "#{error.class}: #{error.message}"
      end
    end

    restore_report =
      if verify_after_rollback
        verify_target_set(model, targets)
      else
        {
          skipped: true,
          missing_pids: [],
          signature_mismatch_pids: []
        }
      end

    integrity_valid =
      abort_error.nil? &&
      restore_report[:missing_pids].empty? &&
      restore_report[:signature_mismatch_pids].empty?

    aggregate = aggregate_samples(samples)
    aggregate[:integrity_valid] = integrity_valid
    aggregate[:operation_abort_error] = abort_error
    aggregate[:restore_report] = restore_report
    aggregate[:batch_wall_seconds] =
      if batch_started && batch_finished
        batch_finished - batch_started
      end

    payload = {
      schema: SCHEMA,
      generated_at: Time.now.iso8601(3),
      label: label.to_s,
      repository: {
        revision: revision,
        short_revision: revision[0, 12]
      },
      runtime: {
        sketchup_version: safe_sketchup_version,
        ruby_version: RUBY_VERSION,
        platform: RUBY_PLATFORM
      },
      model: {
        path: model.path,
        manifest_path: manifest_path,
        manifest_sha256: Digest::SHA256.file(manifest_path).hexdigest
      },
      timing_semantics: {
        built_in_profile: 'inclusive nested stage timing',
        reported_stage_percentages: 'exclusive timing reconstructed from event intervals',
        percentage_denominator: 'sum of diagnostic_profile total_seconds for all targets',
        profiler_changes_geometry_decisions: false,
        profiling_overhead_included: true,
        operation_abort_in_profile_total: false,
        rollback_signature_verification_in_profile_total: false
      },
      target_count: targets.length,
      target_pids: targets.map { |target| target[:pid] },
      aggregate: aggregate,
      samples: samples
    }

    File.open(output_path, 'w:UTF-8') do |file|
      file.write(JSON.pretty_generate(json_safe(payload)))
      file.write("\n")
    end

    $lvn_stage_profile_benchmark_result = payload
    $lvn_stage_profile_benchmark_path = output_path

    print_summary(payload, output_path)
    payload
  rescue StandardError => error
    warn "[LVN STAGE DETAIL PROFILE] FAILED #{error.class}: #{error.message}"
    warn Array(error.backtrace).first(20).join("\n")
    nil
  end

  def profile_target(entity, target)
    allocation_before = GC.stat(:total_allocated_objects)
    outer_started = Process.clock_gettime(CLOCK)

    result = nil
    error = nil
    profile = nil

    begin
      result = lvn_class.normalize(
        entity,
        lvn_class::DEFAULT_TOLERANCE_MM,
        manage_operation: false,
        report: true,
        write_report: false
      )
      profile = result[:diagnostic_profile] if result.is_a?(Hash)
    rescue StandardError => caught
      error = caught
      profile = lvn_class.last_diagnostic_profile if
        lvn_class.respond_to?(:last_diagnostic_profile)
    ensure
      outer_finished = Process.clock_gettime(CLOCK)
      allocation_after = GC.stat(:total_allocated_objects)
    end

    status =
      if error
        :failed
      elsif result.is_a?(Hash) && result[:normalization_skipped] == true
        :skipped
      else
        :success
      end

    stage_analysis = analyze_profile(profile)

    {
      pid: target[:pid],
      label: target[:label],
      source_geometry: target[:geometry],
      status: status,
      strategy: normalization_strategy(result, profile),
      outer_normalize_seconds: outer_finished - outer_started,
      profile_total_seconds: profile && profile[:total_seconds],
      allocated_objects: allocation_after - allocation_before,
      profile_available: !profile.nil?,
      exclusive_stage_seconds: stage_analysis[:exclusive_stage_seconds],
      inclusive_stage_seconds: stage_analysis[:inclusive_stage_seconds],
      exclusive_group_seconds: stage_analysis[:exclusive_group_seconds],
      event_count: stage_analysis[:event_count],
      interval_anomalies: stage_analysis[:interval_anomalies],
      detail_stage_metrics: extract_detail_stage_metrics(profile),
      hotspot_detail: profile.is_a?(Hash) ? profile[:hotspot_detail] : nil,
      error: error ? "#{error.class}: #{error.message}" : nil,
      backtrace: error ? Array(error.backtrace).first(8) : []
    }
  end

  def analyze_profile(profile)
    return empty_profile_analysis unless profile.is_a?(Hash)

    total_seconds = profile[:total_seconds].to_f
    events = Array(profile[:events]).each_with_index.filter_map do |event, index|
      next unless event.is_a?(Hash)

      started = event[:started_after_seconds].to_f
      duration = event[:seconds].to_f
      next if duration.negative?

      {
        index: index,
        stage: event[:stage].to_s,
        started: started,
        finished: started + duration,
        duration: duration,
        children: []
      }
    end

    nodes = events.sort_by do |event|
      [event[:started], -event[:finished], event[:index]]
    end

    roots = []
    stack = []
    anomalies = []

    nodes.each do |node|
      while stack.any? &&
            node[:started] >= stack.last[:finished] - EPSILON_SECONDS
        stack.pop
      end

      parent = stack.last

      if parent &&
         node[:started] >= parent[:started] - EPSILON_SECONDS &&
         node[:finished] <= parent[:finished] + EPSILON_SECONDS
        parent[:children] << node
      else
        if parent
          anomalies << {
            type: 'partial_overlap',
            parent_stage: parent[:stage],
            child_stage: node[:stage],
            parent_interval: [parent[:started], parent[:finished]],
            child_interval: [node[:started], node[:finished]]
          }
          stack.clear
        end
        roots << node
      end

      stack << node
    end

    exclusive = Hash.new(0.0)
    inclusive = Hash.new(0.0)

    nodes.each do |node|
      direct_child_seconds = node[:children].sum do |child|
        child[:duration]
      end

      own_seconds = node[:duration] - direct_child_seconds
      if own_seconds < -EPSILON_SECONDS
        anomalies << {
          type: 'negative_exclusive',
          stage: node[:stage],
          duration: node[:duration],
          direct_child_seconds: direct_child_seconds
        }
      end
      own_seconds = 0.0 if own_seconds.negative?

      exclusive[node[:stage]] += own_seconds
      inclusive[node[:stage]] += node[:duration]
    end

    root_coverage = interval_union_seconds(
      roots.map { |root| [root[:started], root[:finished]] }
    )
    unattributed = total_seconds - root_coverage
    if unattributed < -EPSILON_SECONDS
      anomalies << {
        type: 'root_coverage_exceeds_total',
        total_seconds: total_seconds,
        root_coverage_seconds: root_coverage
      }
    end
    unattributed = 0.0 if unattributed.negative?
    exclusive['unattributed_profile_overhead'] += unattributed

    grouped = Hash.new(0.0)
    exclusive.each do |stage, seconds|
      grouped[stage_group(stage)] += seconds
    end

    {
      event_count: events.length,
      exclusive_stage_seconds: sort_numeric_hash(exclusive),
      inclusive_stage_seconds: sort_numeric_hash(inclusive),
      exclusive_group_seconds: sort_numeric_hash(grouped),
      interval_anomalies: anomalies
    }
  end

  def interval_union_seconds(intervals)
    sorted = Array(intervals)
             .map { |start_at, finish_at| [start_at.to_f, finish_at.to_f] }
             .select { |start_at, finish_at| finish_at >= start_at }
             .sort_by(&:first)
    return 0.0 if sorted.empty?

    total = 0.0
    current_start, current_finish = sorted.first

    sorted.drop(1).each do |start_at, finish_at|
      if start_at <= current_finish + EPSILON_SECONDS
        current_finish = [current_finish, finish_at].max
      else
        total += current_finish - current_start
        current_start = start_at
        current_finish = finish_at
      end
    end

    total + current_finish - current_start
  end

  def aggregate_samples(samples)
    valid_profiles = samples.select { |sample| sample[:profile_available] }
    total_profile_seconds = valid_profiles.sum do |sample|
      sample[:profile_total_seconds].to_f
    end
    total_outer_seconds = samples.sum do |sample|
      sample[:outer_normalize_seconds].to_f
    end

    exclusive_stage = sum_nested_numeric_hashes(
      valid_profiles,
      :exclusive_stage_seconds
    )
    inclusive_stage = sum_nested_numeric_hashes(
      valid_profiles,
      :inclusive_stage_seconds
    )
    exclusive_group = sum_nested_numeric_hashes(
      valid_profiles,
      :exclusive_group_seconds
    )

    {
      status_counts: count_by(samples, :status),
      strategy_counts: count_by(samples, :strategy),
      profile_available_count: valid_profiles.length,
      profile_missing_count: samples.length - valid_profiles.length,
      total_profile_seconds: total_profile_seconds,
      total_outer_normalize_seconds: total_outer_seconds,
      profiling_wrapper_difference_seconds:
        total_outer_seconds - total_profile_seconds,
      total_allocated_objects: samples.sum do |sample|
        sample[:allocated_objects].to_i
      end,
      event_count: valid_profiles.sum { |sample| sample[:event_count].to_i },
      interval_anomaly_count: valid_profiles.sum do |sample|
        Array(sample[:interval_anomalies]).length
      end,
      exclusive_stage_seconds: sort_numeric_hash(exclusive_stage),
      exclusive_stage_percent: percentage_hash(
        exclusive_stage,
        total_profile_seconds
      ),
      inclusive_stage_seconds: sort_numeric_hash(inclusive_stage),
      exclusive_group_seconds: sort_numeric_hash(exclusive_group),
      exclusive_group_percent: percentage_hash(
        exclusive_group,
        total_profile_seconds
      ),
      detail_stage_metrics: aggregate_detail_stage_metrics(valid_profiles),
      hotspot_detail: aggregate_hotspot_detail(valid_profiles),
      strategy_breakdown: strategy_breakdown(samples)
    }
  end

  def extract_detail_stage_metrics(profile)
    return {} unless profile.is_a?(Hash)

    Hash(profile[:stages]).each_with_object({}) do |(name, metrics), result|
      next unless name.to_s.start_with?('detail_')

      result[name.to_s] = {
        calls: metrics[:calls].to_i,
        total_seconds: metrics[:total_seconds].to_f,
        max_seconds: metrics[:max_seconds].to_f,
        failures: metrics[:failures].to_i
      }
    end.sort_by do |_name, metrics|
      -metrics[:total_seconds]
    end.to_h
  end

  def aggregate_detail_stage_metrics(samples)
    totals = {}
    samples.each do |sample|
      Hash(sample[:detail_stage_metrics]).each do |name, metrics|
        target = totals[name.to_s] ||= {
          calls: 0,
          total_seconds: 0.0,
          max_seconds: 0.0,
          failures: 0
        }
        target[:calls] += metrics[:calls].to_i
        target[:total_seconds] += metrics[:total_seconds].to_f
        target[:max_seconds] = [
          target[:max_seconds],
          metrics[:max_seconds].to_f
        ].max
        target[:failures] += metrics[:failures].to_i
      end
    end
    totals.sort_by do |_name, metrics|
      -metrics[:total_seconds]
    end.to_h
  end

  def aggregate_hotspot_detail(samples)
    result = {}
    samples.each do |sample|
      merge_numeric_tree!(result, sample[:hotspot_detail])
    end
    result
  end

  def merge_numeric_tree!(target, source)
    Hash(source).each do |key, value|
      if value.is_a?(Hash)
        target[key] ||= {}
        merge_numeric_tree!(target[key], value)
      elsif value.is_a?(Numeric)
        target[key] = target.fetch(key, 0) + value
      end
    end
    target
  end

  def strategy_breakdown(samples)
    samples.group_by { |sample| sample[:strategy].to_s }.each_with_object({}) do |
      (strategy, strategy_samples),
      result
    |
      profile_samples = strategy_samples.select do |sample|
        sample[:profile_available]
      end
      total = profile_samples.sum do |sample|
        sample[:profile_total_seconds].to_f
      end
      groups = sum_nested_numeric_hashes(
        profile_samples,
        :exclusive_group_seconds
      )

      result[strategy] = {
        count: strategy_samples.length,
        status_counts: count_by(strategy_samples, :status),
        total_profile_seconds: total,
        exclusive_group_seconds: sort_numeric_hash(groups),
        exclusive_group_percent: percentage_hash(groups, total)
      }
    end
  end

  def stage_group(stage)
    name = stage.to_s

    return '00_unattributed_and_profiler_overhead' if
      name == 'unattributed_profile_overhead'

    return '01_public_validation_and_operation_wrapper' if [
      'source_entity_validation',
      'operation_total',
      'unique_definition_check'
    ].include?(name)

    return '02_fast_path_probe_and_exact_validation' if
      name.start_with?('fast_path_')

    return '03_source_snapshot_and_exact_triangulation' if
      name == 'source_brep_snapshot' ||
      name.include?('source_boundary_face_snapshot') ||
      name.include?('exact_polygon_triangulation') ||
      name.include?('exact_ear_clipping') ||
      name.include?('exact_lawson_flip_optimization') ||
      name.include?('source_boundary_validation')

    return '04_vertex_projection_and_sliver_planning' if [
      'axis_plane_plan',
      'vertex_target_metrics',
      'short_edge_sliver_plan',
      'grid_target_projection',
      'source_altitude_sliver_collapse',
      'short_edge_sliver_collapse',
      'sliver_topology_validation'
    ].include?(name)

    return '05_conforming_and_triangle_cleanup' if
      name.start_with?('conforming_') ||
      [
        'triangle_shape_validation',
        'triangle_mesh_inventory',
        'triangle_record_sanitize'
      ].include?(name)

    return '06_closed_mesh_and_intersection_hard_gates' if [
      'closed_mesh_and_intersection_validation',
      'triangle_intersection_validation'
    ].include?(name)

    return '07_sketchup_geometry_rebuild' if [
      'erase_source_geometry',
      'sketchup_face_rebuild',
      'rebuilt_geometry_snapshot',
      'triangle_rebuild_validation'
    ].include?(name)

    return '08_orientation_coplanar_cleanup_and_repairs' if [
      'orient_and_coplanar_cleanup',
      'coplanar_shared_edge_cleanup',
      'final_entity_repair',
      'surface_border_repair',
      'external_face_repair'
    ].include?(name)

    return '09_final_entity_grid_and_surface_validation' if [
      'rebuilt_entity_validation',
      'final_grid_residual',
      'surface_descriptor',
      'surface_equivalence'
    ].include?(name)

    return '10_report_building' if [
      'normalization_report_build',
      'normalization_report_augmentation'
    ].include?(name)

    return '11_final_coplanar_face_merge_and_wrapper' if
      name == 'normalize_entity_total' ||
      name == 'final_coplanar_baseline_snapshot_total'

    return '12_pipeline_dispatch_and_uninstrumented_repairs' if [
      'core_before_final_coplanar_merge',
      'full_rebuild_pipeline'
    ].include?(name)

    '13_other_instrumented_stage'
  end

  def sum_nested_numeric_hashes(samples, key)
    total = Hash.new(0.0)
    samples.each do |sample|
      Hash(sample[key]).each do |name, value|
        total[name.to_s] += value.to_f
      end
    end
    total
  end

  def percentage_hash(values, denominator)
    denominator = denominator.to_f
    return {} unless denominator.positive?

    sort_numeric_hash(
      values.each_with_object({}) do |(name, seconds), result|
        result[name.to_s] = seconds.to_f * 100.0 / denominator
      end
    )
  end

  def sort_numeric_hash(values)
    values.sort_by { |_name, value| -value.to_f }.to_h
  end

  def count_by(samples, key)
    samples.group_by { |sample| sample[key].to_s }
           .transform_values(&:length)
  end

  def empty_profile_analysis
    {
      event_count: 0,
      exclusive_stage_seconds: {},
      inclusive_stage_seconds: {},
      exclusive_group_seconds: {},
      interval_anomalies: []
    }
  end

  def missing_sample(target)
    {
      pid: target[:pid],
      label: target[:label],
      source_geometry: target[:geometry],
      status: :missing,
      strategy: nil,
      outer_normalize_seconds: 0.0,
      profile_total_seconds: nil,
      allocated_objects: 0,
      profile_available: false,
      exclusive_stage_seconds: {},
      inclusive_stage_seconds: {},
      exclusive_group_seconds: {},
      event_count: 0,
      interval_anomalies: [],
      detail_stage_metrics: {},
      hotspot_detail: nil,
      error: 'Target entity was not found',
      backtrace: []
    }
  end

  def print_sample(sample, ordinal, total)
    puts format(
      '[LVN STAGE DETAIL PROFILE] %4d/%-4d PID=%-10d %-7s profile=%10.3fs events=%-7d %s',
      ordinal,
      total,
      sample[:pid],
      sample[:status],
      sample[:profile_total_seconds].to_f,
      sample[:event_count].to_i,
      sample[:label]
    )
  end

  def print_header(model:, revision:, manifest_path:, target_count:)
    puts '=' * 104
    puts ' LVN CURRENT STAGE DETAIL PROFILE BENCHMARK'
    puts '=' * 104
    puts "model            : #{model.path}"
    puts "revision         : #{revision}"
    puts "manifest         : #{manifest_path}"
    puts "targets          : #{target_count}"
    puts format('tolerance        : %.6f mm', lvn_class::DEFAULT_TOLERANCE_MM)
    puts 'profile mode     : report=true, write_report=false'
    puts 'percentage       : exclusive stage time / summed profile total'
    puts 'rollback         : one batch operation, one abort after all targets'
    puts '=' * 104
  end

  def print_summary(payload, output_path)
    aggregate = payload[:aggregate]

    puts
    puts '=' * 104
    puts ' LVN STAGE DETAIL PROFILE RESULT'
    puts '=' * 104
    puts "integrity valid  : #{aggregate[:integrity_valid]}"
    puts "status counts    : #{aggregate[:status_counts].inspect}"
    puts "strategy counts  : #{aggregate[:strategy_counts].inspect}"
    puts format(
      'profile total    : %.3f s',
      aggregate[:total_profile_seconds]
    )
    puts "events           : #{aggregate[:event_count]}"
    puts "interval anomaly : #{aggregate[:interval_anomaly_count]}"
    puts '-' * 104
    puts 'EXCLUSIVE GROUP PERCENTAGES'

    aggregate[:exclusive_group_percent].each do |name, percent|
      seconds = aggregate[:exclusive_group_seconds][name].to_f
      puts format('%7.3f%%  %12.3fs  %s', percent, seconds, name)
    end

    puts '-' * 104
    puts 'DETAIL STAGE TOTALS'
    aggregate[:detail_stage_metrics].each do |name, metrics|
      puts format(
        '%12.3fs  calls=%-9d max=%10.6fs  %s',
        metrics[:total_seconds],
        metrics[:calls],
        metrics[:max_seconds],
        name
      )
    end

    puts '-' * 104
    puts "JSON             : #{output_path}"
    puts '=' * 104
  end

  def install_stage_extensions!
    klass = lvn_class
    return if klass.ancestors.include?(StageProfilerExtensions)

    klass.prepend(StageProfilerExtensions)
  end

  def load_manifest(model, path)
    raise "Manifest not found: #{path}" unless File.file?(path)

    manifest = symbolize_keys(
      JSON.parse(File.read(path, encoding: 'UTF-8'))
    )

    unless manifest[:schema] == MANIFEST_SCHEMA
      raise "Unexpected manifest schema: #{manifest[:schema].inspect}"
    end

    expected_model = File.expand_path(manifest[:model_path].to_s)
    current_model = File.expand_path(model.path.to_s)
    unless expected_model == current_model
      raise "Manifest model differs: #{expected_model} != #{current_model}"
    end

    manifest
  end

  def manifest_targets(manifest)
    Array(manifest[:targets]).map do |record|
      {
        pid: record[:pid].to_i,
        label: record[:label].to_s,
        geometry: symbolize_keys(record[:geometry]),
        signature: record[:signature].to_s
      }
    end
  end

  def verify_target_set!(model, targets)
    report = verify_target_set(model, targets)
    return if report[:missing_pids].empty? &&
              report[:signature_mismatch_pids].empty?

    raise "Target verification failed: #{report.inspect}"
  end

  def verify_target_set(model, targets)
    missing = []
    mismatches = []

    targets.each_with_index do |target, index|
      entity = resolve_top_level_entity(model, target[:pid])

      if entity.nil?
        missing << target[:pid]
        next
      end

      actual = brep_signature(entity)
      mismatches << target[:pid] unless actual == target[:signature]

      puts format(
        '[LVN STAGE DETAIL PROFILE] signature %4d/%-4d PID=%d %s',
        index + 1,
        targets.length,
        target[:pid],
        actual == target[:signature] ? 'OK' : 'MISMATCH'
      )
    end

    {
      missing_pids: missing,
      signature_mismatch_pids: mismatches
    }
  end

  def resolve_top_level_entity(model, pid)
    entity = if model.respond_to?(:find_entity_by_persistent_id)
               model.find_entity_by_persistent_id(pid)
             end

    if entity && top_level_parent?(model, entity.parent)
      return entity
    end

    model.entities.find do |candidate|
      candidate.respond_to?(:persistent_id) &&
        candidate.persistent_id.to_i == pid.to_i
    end
  rescue StandardError
    nil
  end

  def top_level_parent?(model, parent)
    parent == model || parent == model.entities
  rescue StandardError
    false
  end

  def brep_signature(entity)
    entities = entity.definition.entities
    faces = entities.grep(Sketchup::Face).select(&:valid?)
    edges = entities.grep(Sketchup::Edge).select(&:valid?)
    vertices = edges.flat_map(&:vertices).select(&:valid?).uniq

    vertex_keys = vertices.map do |vertex|
      point_key(vertex.position)
    end.sort

    edge_keys = edges.map do |edge|
      edge.vertices.map { |vertex| point_key(vertex.position) }
          .sort
          .join('>')
    end.sort

    face_keys = faces.map do |face|
      loops = face.loops.map do |loop|
        points = loop.vertices.map { |vertex| point_key(vertex.position) }
        marker = loop == face.outer_loop ? 'O' : 'H'
        "#{marker}:#{canonical_oriented_cycle(points)}"
      end.sort

      "#{vector_key(face.normal)}|#{loops.join('|')}"
    end.sort

    payload = [
      "V=#{vertex_keys.length}",
      vertex_keys.join(';'),
      "E=#{edge_keys.length}",
      edge_keys.join(';'),
      "F=#{face_keys.length}",
      face_keys.join(';')
    ].join("\n")

    Digest::SHA256.hexdigest(payload)
  end

  def canonical_oriented_cycle(values)
    values = Array(values)
    return '' if values.empty?

    values.length.times.map do |offset|
      values.rotate(offset).join('>')
    end.min
  end

  def point_key(point)
    [
      float_key(point.x),
      float_key(point.y),
      float_key(point.z)
    ].join(',')
  end

  def vector_key(vector)
    [
      float_key(vector.x),
      float_key(vector.y),
      float_key(vector.z)
    ].join(',')
  end

  def float_key(value)
    format('%.17g', value.to_f)
  end

  def normalization_strategy(result, profile)
    return result[:normalization_strategy] if
      result.is_a?(Hash) && result[:normalization_strategy]

    if profile.is_a?(Hash)
      value = profile.dig(:normalization_result, :normalization_strategy)
      return value if value
    end

    result.is_a?(Hash) && result[:normalization_skipped] ? :skipped : nil
  rescue StandardError
    nil
  end

  def lvn_class
    ULOL::Indoor3DGmlModeler::IndoorCore::LocalVertexNormalizer
  end

  def default_manifest_path(model)
    directory = File.dirname(model.path)
    basename = File.basename(model.path, File.extname(model.path))
    File.join(directory, "#{basename}_lvn_many_solids_targets.json")
  end

  def ensure_saved_model!(model)
    path = model.path.to_s
    raise 'Save the SketchUp model before profiling' if path.empty?
    raise "SketchUp model path does not exist: #{path}" unless File.file?(path)
  end

  def safe_sketchup_version
    Sketchup.version
  rescue StandardError
    nil
  end

  def sanitize_label(value)
    value.to_s.gsub(/[\\\/:*?"<>|]/, '_')
  end

  def symbolize_keys(value)
    case value
    when Hash
      value.each_with_object({}) do |(key, item), result|
        result[key.to_sym] = symbolize_keys(item)
      end
    when Array
      value.map { |item| symbolize_keys(item) }
    else
      value
    end
  end

  def json_safe(value)
    case value
    when Hash
      value.each_with_object({}) do |(key, item), result|
        result[key.to_s] = json_safe(item)
      end
    when Array
      value.map { |item| json_safe(item) }
    when Symbol
      value.to_s
    when Float
      value.finite? ? value : value.to_s
    else
      value
    end
  end
end
